def problem_011(k: int = 4) -> int:
    """
    1) find max product of horizontal adjacent numbers;
    2) find max product of vertical adjacent numbers;
    3) find max product of main_diagonal adjacent numbers;
    4) find max product of anti_diagonal adjacent numbers;
    5) take max of 1) - 4).

    - O(1) space-complexity
    """
    horizontal = horizontal_adjacent_numbers(k)
    vertical = vertical_adjacent_numbers(k)
    main_diagonal = main_diagonal_adjacent_numbers(k)
    anti_diagonal = anti_diagonal_adjacent_numbers(k)
    return max(horizontal, vertical, main_diagonal, anti_diagonal)
